	@Test
	void completeMetadataQuotesSetupAndContractionWithoutOpeningInput() {
		try (Fixture fixture = new Fixture(4096L, 4096L, 64L, 64L, 64L, 64L, false)) {
			NativeAggregatePhysicalPlan.Work work = fixture.plan.quote(fixture.row);
			assertNotNull(work, "bounded adjacency metadata must make the sparse producer normally priceable");
			assertTrue(work.input().workEvidence().isComplete());
			LmdbNativeCostVector operations = work.input().operations().plus(work.extra());
			assertTrue(operations.high(SCANNED_ROW) >= 8192D, "both input planes must be read");
			assertTrue(operations.high(HASH_BUILD_ROW) > 0D, "shared and endpoint remapping is real setup");
			assertTrue(operations.high(HASH_PROBE) >= 4096D, "left fibers probe the shared-key dictionary");
			assertTrue(operations.high(GROUP_UPDATE) >= 262144D,
					"the fully connected fixture can require one update per a/j/b combination");
			assertEquals(0D, work.input().lowRows(), "cardinalities alone do not prove shared-domain overlap");
			assertTrue(work.input().highRows() <= 4096D,
					"completed groups are bounded by the endpoint cross product");
			assertNotNull(fixture.plan.coldAnchor(fixture.row, work),
					"a branching sparse reduction with bounded state must be a cold normal candidate");
			verify(fixture.source, never()).newProbe();
		}
	}

