		try (Fixture forward = new Fixture(1024L, 2048L, 64L, 256L, 1024L, 64L, false);
				Fixture reverse = new Fixture(2048L, 1024L, 64L, 1024L, 256L, 64L, false)) {
			NativeAggregatePhysicalPlan.Work work = forward.plan.quote(forward.row);
			NativeAggregatePhysicalPlan.Work transposed = reverse.plan.quote(reverse.row);
			assertNotNull(work);
			assertNotNull(transposed);
			assertEquals(2048D, work.extra().expected(GROUP_UPDATE),
					"the larger shared domain limits expected overlap under uniformity and containment");
			assertEquals(65536D, work.extra().high(GROUP_UPDATE));
			assertEquals(2048D, work.input().rows(), "expected groups cannot exceed expected products");
			assertEquals(0D, work.input().lowRows());
			assertEquals(4096D, work.input().highRows(), "skew may still populate every endpoint pair");
			assertEquals(work.extra().expected(GROUP_UPDATE), transposed.extra().expected(GROUP_UPDATE));
			assertEquals(work.input().rows(), transposed.input().rows());
			assertEquals(work.input().highRows(), transposed.input().highRows());
			verify(forward.source, never()).newProbe();
			verify(reverse.source, never()).newProbe();
		}
